class Fahrzeug
{
    public virtual string Info()
        => "Fahrzeug";
}
class Auto : Fahrzeug
{
    public override string Info()
        => "Auto";
}
class Fahrrad : Fahrzeug
{
    public override string Info()
        => base.Info() + " ohne Motor";
}

List<Fahrzeug> fz =
    [new Auto(), new Fahrrad()];
foreach (var f in fz)
    Console.WriteLine(f.Info());
// Auto
// Fahrzeug ohne Motor

class Tier
{
    public string Laut() => "...";
}
class Hund : Tier
{
    public new string Laut() => "Wuff";
}

Tier t = new Hund();
Console.WriteLine(t.Laut()); // ...
Hund h = new Hund();
Console.WriteLine(h.Laut()); // Wuff

abstract class Form
{
    public abstract double Flaeche();
}
class Rechteck(double a, double b)
    : Form
{
    public override double Flaeche()
        => a * b;
}
class Kreis(double r) : Form
{
    public override double Flaeche()
        => Math.PI * r * r;
}

Form[] formen =
    [new Kreis(1), new Rechteck(2, 3)];
double summe = 0;
foreach (var f in formen)
    summe += f.Flaeche();
Console.WriteLine($"{summe:F2}"); // 9.14

interface IDruckbar
{
    void Drucken();
}
class Zeugnis : IDruckbar
{
    public void Drucken() =>
        Console.WriteLine("Druckt...");
}

IDruckbar d = new Zeugnis();
d.Drucken();

object o = new Zeugnis();
if (o is IDruckbar x)  // Typprüfung
    x.Drucken();

